Set Kernel Conversion Dep Heuristic.

Definition choose (y : nat) (b : bool) (x : nat) := if b then x else y.
Fixpoint duplicate (n : nat) : nat :=
  match n with O => O | S k => Nat.add (duplicate k) (duplicate k) end.
Definition indirect (n : nat) := choose n true (duplicate 32).
Definition expensive (n : nat) := indirect n.
Strategy -10 [choose].
Strategy 10 [expensive indirect].

(* Keep a large unused branch explicit as a closure-probe control.
   [expensive] reaches [choose] through [indirect], while selecting the
   true branch immediately returns the shared argument. *)
