Definition wrong_branch (n : nat) : n = choose n true (S n).
Proof. exact_no_check (eq_refl n). Timeout 5 Fail Qed. Abort.
Definition hidden (n : nat) : nat.
Proof. exact n. Qed.
Definition opaque_branch (n : nat) : n = choose n true (hidden n).
Proof. exact_no_check (eq_refl n). Timeout 5 Fail Qed. Abort.
